#!/usr/bin/env bash

set -euo pipefail

MODULE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
DOTFILES="$(cd "$MODULE_DIR/../.." && pwd)"

source "$DOTFILES/scripts/common.sh"
source "$DOTFILES/scripts/links.sh"

log "Configuring Hyprland (Lua configuration)"

HYPR_DIR="$HOME/.config/hypr"
mkdir -p \
	"$HYPR_DIR" \
	"$HYPR_DIR/hyprland/shellOverrides" \
	"$HYPR_DIR/hyprlock" \
	"$HYPR_DIR/custom/scripts"

# Runtime-generated files (matugen / Quickshell) stay local so writing them
# never dirties the dotfiles repository. They are seeded from the repo once.
copy_if_missing() {
	local source="$1"
	local target="$2"

	if [[ -L "$target" ]]; then
		rm -f "$target"
	fi
	if [[ ! -e "$target" ]]; then
		cp "$source" "$target"
		echo " $target (seeded)"
	fi
}

# Entrypoint and static library
link_file "$MODULE_DIR/files/hyprland.lua" "$HYPR_DIR/hyprland.lua"

for file in env execs general keybinds rules variables; do
	link_file \
		"$MODULE_DIR/files/hyprland/$file.lua" \
		"$HYPR_DIR/hyprland/$file.lua"
done

link_dir "$MODULE_DIR/files/hyprland/lib" "$HYPR_DIR/hyprland/lib"
link_dir "$MODULE_DIR/files/hyprland/scripts" "$HYPR_DIR/hyprland/scripts"
link_dir "$MODULE_DIR/files/hyprland/services" "$HYPR_DIR/hyprland/services"

# Generated by matugen / the Quickshell settings UI
copy_if_missing \
	"$MODULE_DIR/files/hyprland/colors.lua" \
	"$HYPR_DIR/hyprland/colors.lua"
copy_if_missing \
	"$MODULE_DIR/files/hyprland/shellOverrides/main.lua" \
	"$HYPR_DIR/hyprland/shellOverrides/main.lua"

# Idle management is rewritten by the Quickshell idle settings UI.
copy_if_missing "$MODULE_DIR/files/hypridle.conf" "$HYPR_DIR/hypridle.conf"

# Lock screen
link_file "$MODULE_DIR/files/hyprlock.conf" "$HYPR_DIR/hyprlock.conf"
link_file \
	"$MODULE_DIR/files/hyprlock/check-capslock.sh" \
	"$HYPR_DIR/hyprlock/check-capslock.sh"
link_file \
	"$MODULE_DIR/files/hyprlock/status.sh" \
	"$HYPR_DIR/hyprlock/status.sh"
copy_if_missing \
	"$MODULE_DIR/files/hyprlock/colors.conf" \
	"$HYPR_DIR/hyprlock/colors.conf"
chmod +x "$HYPR_DIR/hyprlock/check-capslock.sh" "$HYPR_DIR/hyprlock/status.sh"

# Personal overrides
for file in env execs general keybinds rules variables; do
	link_file \
		"$MODULE_DIR/files/custom/$file.lua" \
		"$HYPR_DIR/custom/$file.lua"
done

# switchwall.sh rewrites this file when a video wallpaper is selected.
copy_if_missing \
	"$MODULE_DIR/files/custom/scripts/__restore_video_wallpaper.sh" \
	"$HYPR_DIR/custom/scripts/__restore_video_wallpaper.sh"
chmod +x "$HYPR_DIR/custom/scripts/__restore_video_wallpaper.sh"

success "Hyprland configured"
